Ant Field Kit 19.95Sugar & Water Feeder 7.50Tunnel Kit — Mini 12.00



// SCRIPT_SENTINEL: script text is intentionally inside body.
const entries = [
 {sku:'A101', title:'Ant Field Kit', currency:'USD', price:'19.95', href:'/p/a101', stock:'in'},
 {sku:'B202', title:'Sugar & Water Feeder', currency:'USD', price:'7.50', href:'/p/b202', stock:null},
 {sku:'C303', title:'Tunnel Kit — Mini', currency:'USD', price:'12.00', href:'/p/c303', stock:'out'}
];
function makeCard(row) {
 const card=document.createElement('article'); card.className='card'; card.dataset.sku=row.sku;
 const link=document.createElement('a'); link.className='title'; link.href=row.href; link.textContent=row.title;
 if(row.stock !== null) link.dataset.stock=row.stock;
 const price=document.createElement('span'); price.className='price'; price.dataset.currency=row.currency; price.textContent=row.price;
 card.append(link, document.createTextNode(' '), price); return card;
}
window.releaseCatalog=()=>new Promise(resolve=>requestAnimationFrame(()=>{
 const catalog=document.querySelector('#catalog'); catalog.replaceChildren(...entries.map(makeCard)); catalog.dataset.ready='yes'; resolve('populated');
}));
window.replaceFirst=()=>{
 const row={...entries[0],title:'Ant Field Kit — revised'};
 document.querySelector('#catalog .card').replaceWith(makeCard(row));
 return 'replaced';
};
const shadow=document.querySelector('#shadow-host').attachShadow({mode:'open'});
shadow.append(makeCard({sku:'SHADOW',title:'Shadow product',currency:'USD',price:'4.00',href:'/p/shadow',stock:null}));
